solution:
def pair_in_sorted(nums: list[int], target: int) -> list[int]:
    lo, hi = 0, len(nums) - 1
    while lo < hi:
        s = nums[lo] + nums[hi]
        if s == target:
            return [lo, hi]
        if s < target:
            lo += 1          # nums[lo] is too small even with the largest value left
        else:
            hi -= 1          # nums[hi] is too big even with the smallest value left
    return []

